/*
 * J2ME Emulator - JSR 184 Mobile 3D Graphics API (Software Implementation)
 * 
 * This implements the M3G (Mobile 3D Graphics) API in pure software mode.
 * JSR 184 provides a retained-mode 3D graphics API for mobile devices.
 * 
 * Implemented features:
 * - Graphics3D rendering context
 * - Transform (4x4 matrix operations)
 * - VertexArray (vertex data storage)
 * - IndexBuffer (triangle indices)
 * - Mesh (renderable 3D objects)
 * - Camera (view/projection)
 * - Light (directional, point, spot)
 * - Material and Texture2D
 * - Background
 * - World (scene graph)
 * - Software rasterization with Z-buffer
 */

#ifndef _WIN32
#define _POSIX_C_SOURCE 200809L  /* For strdup */
#endif

#include <stdio.h>
#include "debug.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdint.h>
#include <time.h>      /* v34.96: clock_gettime/nanosleep for the M3G-LOCK watchdog */
#if defined(_WIN32)
/* No <pthread.h> on plain MinGW targets — use the Win32 shim */
#include "win_thread_shim.h"
#else
#include <pthread.h>
#endif

/* MinGW build fix: windows.h (pulled in via win_thread_shim.h on MinGW)
 * defines `near` and `far` as EMPTY legacy macros (Win16 pointer keywords).
 * This file uses `near`/`far` as ordinary identifiers (M3G camera plane
 * distances, m3g_transform_perspective parameters), so strip the macros
 * for the rest of this translation unit. Harmless no-op on POSIX builds. */
#undef near
#undef far

/* FIX(mt-race): M3G software-renderer state (g_m3g.* buffers, texture cache,
 * pending-render queue) is shared between the MIDP paint pump (which runs both
 * on the main thread and inside game threads via thread_yield -> repaints)
 * and the game's own Graphics3D calls. Concurrent m3g_context_init() freed
 * color/depth buffers while another thread was rasterizing into them:
 * heap-use-after-free in m3g_rasterize_triangle followed by double free.
 * Serialize the whole pipeline with one RECURSIVE mutex held for the entire
 * public entry point (force_render / bindTarget / releaseTarget / clear /
 * renderWorld / render(node)). Recursive because internal helpers may be
 * invoked again from within an already-held region. */
static pthread_mutex_t g_m3g_pipeline_lock;

static pthread_mutex_t g_m3g_ui_lock;
static void m3g_pipeline_lock_init_impl(void);

/* v35.00 KILL-ONCE: pthread_once is REMOVED from the M3G acquire path.
 *
 * The v34.99 field trace proved by elimination that the main thread froze
 * INSIDE bindTarget BEFORE the bind body started (last_native=bindTarget,
 * bind_inflight=0, bn stale at 13, ui/pipe both locked=0, no
 * [M3G-LOCK-WAIT]): the only silent, unbounded, non-logging blocking
 * primitive left in that range was pthread_once (the bounded locks log
 * every 5 s, the body sets bind_inflight=1). The devkitA64 pthread_once
 * implementation blocked forever — every observable field matches, and
 * nothing else in the range can block silently.
 *
 * Replacement: a CAS-based one-shot with a LOUD bounded wait. State:
 * 0 = uninitialized, 1 = initializing, 2 = ready. Fast path is a single
 * acquire load; the slow path takes over the init after 3 s (init itself
 * takes microseconds — a 3 s stall means the initializer is provably
 * wedged, and taking over beats freezing forever). */
static volatile int g_m3g_locks_state = 0;

static void m3g_ensure_locks_init(void);

static void m3g_pipeline_lock_init_impl(void) {
    pthread_mutexattr_t uattr;
    pthread_mutexattr_init(&uattr);
    pthread_mutexattr_settype(&uattr, PTHREAD_MUTEX_RECURSIVE);
#ifdef PTHREAD_PRIO_NONE
    pthread_mutexattr_setprotocol(&uattr, PTHREAD_PRIO_NONE);
#endif
    pthread_mutex_init(&g_m3g_ui_lock, &uattr);
    pthread_mutexattr_destroy(&uattr);

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    /* FIX(tpp): explicit RECURSIVE + PRIO_NONE. The previous
     * PTHREAD_RECURSIVE_MUTEX_INITIALIZER_NP default-initialised mutex was
     * implicated in sporadic glibc "tpp.c:86" assertions when many game
     * threads contended here; explicit PRIO_NONE keeps the kernel out of
     * priority-inheritance bookkeeping entirely. */
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
#ifdef PTHREAD_PRIO_NONE
    pthread_mutexattr_setprotocol(&attr, PTHREAD_PRIO_NONE);
#endif
    pthread_mutex_init(&g_m3g_pipeline_lock, &attr);
    pthread_mutexattr_destroy(&attr);
}

static inline void m3g_pipeline_lock_acquire(void);

/* v34.96 M3G-LOCK WATCHDOG — owner tracking + bounded acquisition.
 * The v34.95 freeze trace (STUCK: stage=repaints, td m: nat=Graphics3D age=5972,
 * sp=0, no monenter, rasterizer provably bounded) leaves exactly one blocking
 * point inside a Graphics3D native: the unbounded pthread_mutex_lock() on
 * g_m3g_ui_lock / g_m3g_pipeline_lock below. If ANY thread ever escapes its
 * M3G frame without running the cleanup guards (a wedged nested call, a
 * future longjmp/abort path, an exotic libnx pthread unlock failure), the
 * orphaned recursive mutex blocks EVERY later Graphics3D call FOREVER —
 * precisely the observed signature (the dumped threads are innocent: the
 * holder no longer exists in any state the dump can see).
 * Fix: acquisition is a bounded trylock loop. Every 5 s of waiting it logs
 * WHO holds the lock (JavaThread id + the owner's last native + held-for);
 * if the recorded owner thread is DEAD the lock is provably orphaned and is
 * reinitialized (self-heal); as a last resort after 20 s the lock is stolen
 * regardless — a one-frame graphics glitch is always better than a frozen
 * console. Acquiring threads record themselves, releasing guards clear the
 * flag, so the wait logs always name the CURRENT (or last) owner. */
static volatile int g_m3g_ui_locked = 0;
static volatile int g_m3g_ui_owner_tid = -1;
static volatile long long g_m3g_ui_owner_ms = 0;
static char g_m3g_ui_owner_nat[80];
static volatile int g_m3g_pipe_locked = 0;
static volatile int g_m3g_pipe_owner_tid = -1;
static volatile long long g_m3g_pipe_owner_ms = 0;
static char g_m3g_pipe_owner_nat[80];
static pthread_mutexattr_t g_m3g_rec_attr;   /* kept for re-init recovery */
static int g_m3g_rec_attr_ready = 0;

static void m3g_ui_lock_count_acquire(void);
static void m3g_guard_release(void* guard_ptr);

#define M3G_PASTE_IMPL(a, b) a##b
#define M3G_PASTE(a, b) M3G_PASTE_IMPL(a, b)

/* --- Shared UI/pipeline ordering --------------------------------------
 * All public render entries must take BOTH locks in the same order
 * (ui -> pipeline) and HOLD them until the end of the enclosing block.
 * Place as FIRST statement of an entry point; the cleanup attributes
 * unlock in reverse order (pipeline, then ui) on every exit path.
 * The repaint pump takes only the UI lock; force_render takes only the
 * pipeline lock but runs exclusively inside a UI owner. Consistent
 * ordering removes cross-thread interleaving windows. v34.96: both
 * acquisitions are BOUNDED (see the M3G-LOCK WATCHDOG comment above). */
#define M3G_PIPELINE_LOCK() \
    pthread_mutex_t* M3G_PASTE(_m3g_ui_guard_, __LINE__) \
        __attribute__((cleanup(m3g_guard_release))) = \
        (m3g_ui_lock_count_acquire(), &g_m3g_ui_lock); \
    pthread_mutex_t* M3G_PASTE(_m3g_pipe_guard_, __LINE__) \
        __attribute__((cleanup(m3g_guard_release))) = \
        (m3g_pipeline_lock_acquire(), &g_m3g_pipeline_lock)

