/* Material.setColor(int target, int ARGB) */
static JavaValue native_material_setColor(JVM* jvm, JavaThread* thread,
                                           JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    jint target = args[1].i;
    jint argb = args[2].i;
    
    if (!obj) return NATIVE_RETURN_VOID();
    
    /* v31 FIX: JSR-184 setColor takes an ENUM (AMBIENT=32, DIFFUSE=33,
     * EMISSIVE=34, SPECULAR=35), not a bitmask. The old code only accepted
     * the internal bitmask 1/2/4/8 — with the (previously missing) stub
     * constants returning 0, every setColor call silently dropped the
     * color and materials stayed zero/black. Accept the real enum first,
     * then the legacy bitmask (1/2/4/8), then the 1024-shifted block some
     * third-party stubs use. */
    jint hits = 0;
    switch (target) {
        case 32: m3g_set_int_field(obj, "ambient", argb);  hits |= 1; break;
        case 33: m3g_set_int_field(obj, "diffuse", argb);  hits |= 2; break;
        case 34: m3g_set_int_field(obj, "emissive", argb); hits |= 4; break;
        case 35: m3g_set_int_field(obj, "specular", argb); hits |= 8; break;
        default: {
            if (target & M3G_MATERIAL_AMBIENT) {
                m3g_set_int_field(obj, "ambient", argb);
                hits |= 1;
            }
            if (target & M3G_MATERIAL_DIFFUSE) {
                m3g_set_int_field(obj, "diffuse", argb);
                hits |= 2;
            }
            if (target & M3G_MATERIAL_SPECULAR) {
                m3g_set_int_field(obj, "specular", argb);
                hits |= 8;
            }
            if (target & M3G_MATERIAL_EMISSIVE) {
                m3g_set_int_field(obj, "emissive", argb);
                hits |= 4;
            }
            break;
        }
    }
    (void)hits;
    
    GFX_DEBUG("Material.setColor: target=%d, ARGB=0x%08X", target, argb);
    return NATIVE_RETURN_VOID();
}

