/* Appearance.setTexture(int index, Texture2D) */
static JavaValue native_appearance_setTexture(JVM* jvm, JavaThread* thread,
                                                JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    jint index = args[1].i;
    JavaObject* texture = (JavaObject*)args[2].ref;
    
    if (!obj) return NATIVE_RETURN_VOID();
    if (index == 0) {
        m3g_set_ref_field(obj, "texture", texture);
    } else if (index == 1) {
        /* v30 FIX (JSR-184 §Appearance.setTexture): unit 1 was silently
         * dropped — multitextured meshes rendered with the base layer only. */
        m3g_set_ref_field(obj, "texture1", texture);
    }
    /* v18 TRACE: prove setTexture links the texture (throttled) */
    {
        static int trace_count = 0;
        static int nonnull_count = 0;
        if (texture) {
            nonnull_count++;
            if (nonnull_count < 40) {
                JavaFrame* cf = (thread && thread->current_frame) ? thread->current_frame : NULL;
                LOG_SAFE("[M3G-TRACE] Appearance.setTexture NONNULL #%d index=%d texture=%p caller=%s.%s\n",
                         nonnull_count, index, (void*)texture,
                         (cf && cf->clazz && cf->clazz->class_name) ? cf->clazz->class_name : "?",
                         (cf && cf->method && cf->method->name) ? cf->method->name : "?");
            }
        }
        if (trace_count < 32) {
            trace_count++;
            LOG_SAFE("[M3G-TRACE] Appearance.setTexture #%d index=%d texture=%p\n",
                     trace_count, index, (void*)texture);
        }
    }
    /* TEMP-DIAG (session 36): log Java stack for NULL textures */
    if (!texture && thread && thread->current_frame) {
        static int null_log_count = 0;
        if (null_log_count < 40) {
            null_log_count++;
            char stk[1024];
            int pos = 0;
            JavaFrame* f = thread->current_frame;
            int n = 0;
            while (f && n < 12 && pos < (int)sizeof(stk) - 96) {
                const char* cls = (f->clazz && f->clazz->class_name) ? f->clazz->class_name : "?";
                const char* slash = strrchr(cls, '/');
                const char* short_cls = slash ? slash + 1 : cls;
                const char* meth = (f->method && f->method->name) ? f->method->name : "?";
                pos += snprintf(stk + pos, sizeof(stk) - pos, " %s.%s(pc=%d)", short_cls, meth, (int)f->pc);
                f = f->prev;
                n++;
            }
            LOG_SAFE("[NULLTEX] Appearance.setTexture #%d index=%d STACK:%s\n", null_log_count, index, stk);
        }
    }

    GFX_DEBUG("Appearance.setTexture: index=%d, texture=%p", index, (void*)texture);
    return NATIVE_RETURN_VOID();
}

/* Texture2D.<init>(Image2D) */
static JavaValue native_texture2d_init(JVM* jvm, JavaThread* thread,
                                        JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    JavaObject* image = (JavaObject*)args[1].ref;

    if (!obj) return NATIVE_RETURN_VOID();

    /* v18 TRACE: prove the texture ctor runs (throttled to first 32 calls) */
    {
        static int trace_count = 0;
        if (trace_count < 32) {
            trace_count++;
            LOG_SAFE("[M3G-TRACE] Texture2D.<init>(Image2D) #%d obj=%p image=%p\n",
                     trace_count, (void*)obj, (void*)image);
        }
    }

    /* Get image data using helper functions */
    if (image) {
        m3g_set_ref_field(obj, "pixels", m3g_get_ref_field(image, "pixels"));
        m3g_set_int_field(obj, "width", m3g_get_int_field(image, "width", 64));
        m3g_set_int_field(obj, "height", m3g_get_int_field(image, "height", 64));
        /* v14 FIX: the constructor used to DROP the reference to the Image2D
         * itself. m3g_build_texture2d resolves the image via the tex-image
         * map or the "image" field; without either it hit TEXBUILD-FAIL and
         * every API-created Texture2D rendered textureless (M3GTest scene 4).
         * Register the image both ways. */
        m3g_set_ref_field(obj, "image", image);
        m3g_store_tex_image_map(obj, image);
    }
    
    GFX_DEBUG("Texture2D.<init>: image=%p", (void*)image);
    return NATIVE_RETURN_VOID();
}

/* Texture2D.setFiltering(int level) / setFiltering(level, imageFilter) —
 * v23; v34.32: the two-argument JSR-184 1.1 form stores the image filter
 * too (previously the second parameter was silently dropped). The software
 * rasterizer samples bilinearly at most, so only the NEAREST/FIRST-LEVEL
 * distinction is honored; both values round-trip through getFiltering.
 * level = FILTER_BASE_LEVEL(208) → nearest, FILTER_LINEAR(209) → bilinear,
 * FILTER_TRILINEAR(211) → bilinear on base level (no mips in software raster). */
static JavaValue native_texture2d_setFiltering(JVM* jvm, JavaThread* thread,
                                                JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    jint level = args[1].i;

    if (obj) {
        m3g_set_int_field(obj, "filtering", level);
        if (arg_count >= 3) {
            m3g_set_int_field(obj, "imageFiltering", args[2].i);
        }
        /* Refresh a texture that is already built so the change is visible */
        M3GTexture2D* tex = m3g_lookup_texture_cache(obj);
        if (tex) tex->filter_level = (int)level;
    }

    GFX_DEBUG("Texture2D.setFiltering: level=%d image=%d", level,
              arg_count >= 3 ? args[2].i : -1);
    return NATIVE_RETURN_VOID();
}

/* Texture2D.getFiltering(int[] params) — JSR-184 1.1 getter (v34.32):
 * params[0] = level filter, params[1] = image filter. */
static JavaValue native_texture2d_getFiltering(JVM* jvm, JavaThread* thread,
                                                JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    JavaArray* params = (JavaArray*)args[1].ref;
    if (!obj || !params || params->element_type != T_INT) return NATIVE_RETURN_VOID();
    jint* out = (jint*)array_data(params);
    if (params->length > 0) out[0] = m3g_get_int_field(obj, "filtering", 208);
    if (params->length > 1) out[1] = m3g_get_int_field(obj, "imageFiltering", 210);
    return NATIVE_RETURN_VOID();
}

