/* ---- Group.pick(scope, x, y, Camera, RayIntersection) — screen-space pick
 * per JSR-184 §Group implementation guidelines: "The pick ray is cast
 * towards infinity from the given point p on the near clipping plane,
 * through a point p' on the far clipping plane. ... Applying the inverse
 * projection matrix on the pick points, we obtain their positions in camera
 * space: pc = P^-1 * pndc, p'c = P^-1 * p'ndc. We then scale the resultant
 * coordinates: p = pc / w, p' = p'c / w'. The origin of the pick ray in
 * camera coordinates is then p while its direction vector is p' - p.
 * Finally, the pick ray is transformed from camera space to the coordinate
 * system of this Group."
 * v34.69 AUDIT FIXES vs the previous implementation:
 *  - SPEC SIGNATURE is pick(int, float, float, Camera, RayIntersection) —
 *    the registered descriptor was (III...)Z, which no spec-compiled caller
 *    could ever match (NoSuchMethodError). Now registered exactly; the old
 *    int-arg form is kept as a legacy wrapper.
 *  - Ray origin is the NEAR-CLIP PLANE point (javadoc: "the distance ...
 *    is not the distance from the camera, but the distance from the point
 *    p"), not the eye.
 *  - The ray is unprojected through the ACTUAL projection matrix (the
 *    camera's cached matrix — perspective, parallel AND generic all work);
 *    previously a fov/aspect cone was rebuilt, breaking parallel/generic
 *    cameras entirely.
 *  - Camera pose uses the WORLD (composite) transform — a camera nested in
 *    a Group (JSR-184 defect A family) was picked from its local pose.
 *  - The world-space ray is then converted into THIS GROUP's coordinate
 *    system (inverse composite), as the spec requires — previously the ray
 *    was left in world space, so a transformed Group picked wrong. ---- */

static JavaValue native_group_pick_f(JVM* jvm, JavaThread* thread,
                                     JavaValue* args, int arg_count) {
    (void)thread; (void)arg_count;
    /* args: (this, scope, x:float, y:float, camera, rayIntersection) */
    JavaObject* group = (JavaObject*)args[0].ref;
    jint scope = args[1].i;
    jfloat sx = args[2].f, sy = args[3].f;
    JavaObject* camera = (JavaObject*)args[4].ref;
    JavaObject* ri = (JavaObject*)args[5].ref;
    if (!group || !camera || !ri) return NATIVE_RETURN_INT(0);

    /* 1. Projection matrix: prefer the camera's cached matrix (setPerspective/
     * setParallel/setGeneric all maintain it), rebuild from fields otherwise. */
    M3GTransform proj;
    {
        JavaArray* cache = (JavaArray*)m3g_get_ref_field(camera, "genericMatrix");
        const jfloat* cached = (cache && cache->element_type == T_FLOAT &&
                                cache->length >= 16) ? (jfloat*)array_data(cache) : NULL;
        if (cached) {
            for (int i = 0; i < 16; i++) proj.m[i] = cached[i];
        } else {
            jint ptype = m3g_get_int_field(camera, "projectionType", 0);
            if (ptype == 1) {
                float h = m3g_get_float_field(camera, "height", 2.0f);
                float a = m3g_get_float_field(camera, "aspect", 1.0f);
                float n = m3g_get_float_field(camera, "near", 0.1f);
                float f = m3g_get_float_field(camera, "far", 100.0f);
                m3g_transform_ortho(&proj, -h * a * 0.5f, h * a * 0.5f, -h * 0.5f, h * 0.5f, n, f);
            } else {
                float fov = m3g_get_float_field(camera, "fov", 50.0f);
                float a = m3g_get_float_field(camera, "aspect", 1.0f);
                float n = m3g_get_float_field(camera, "near", 0.1f);
                float f = m3g_get_float_field(camera, "far", 100.0f);
                m3g_transform_perspective(&proj, fov, a, n, f);
            }
        }
    }
    M3GTransform proj_inv;
    if (!m3g_transform_invert(&proj_inv, &proj)) {
        /* spec: projection must be invertible; bail out as "no hit" */
        return NATIVE_RETURN_INT(0);
    }

    /* 2. Viewport pixel -> NDC -> near/far plane points -> camera-space ray */
    float vw = (float)(g_m3g.viewport_width  > 0 ? g_m3g.viewport_width  : 240);
    float vh = (float)(g_m3g.viewport_height > 0 ? g_m3g.viewport_height : 320);
    float ndc_x = (2.0f * sx / vw) - 1.0f;
    float ndc_y = 1.0f - (2.0f * sy / vh);

    float pn[4] = { ndc_x, ndc_y, -1.0f, 1.0f };
    float pf[4] = { ndc_x, ndc_y,  1.0f, 1.0f };
    float pc[4], pfc[4];
    m3g_transform_point(pc,  &proj_inv, pn);
    m3g_transform_point(pfc, &proj_inv, pf);
    if (fabsf(pc[3])  < 1e-12f || fabsf(pfc[3]) < 1e-12f) return NATIVE_RETURN_INT(0);
    float o_cam[3] = { pc[0] / pc[3],  pc[1] / pc[3],  pc[2] / pc[3] };
    float d_cam[3] = { pfc[0] / pfc[3] - o_cam[0],
                       pfc[1] / pfc[3] - o_cam[1],
                       pfc[2] / pfc[3] - o_cam[2] };

    /* 3. Camera space -> world (camera composite/world transform) */
    M3GTransform cam_world;
    m3g_node_world_and_parent(camera, &cam_world, NULL);
    float o_world[4], d_world[4];
    float o4[4] = { o_cam[0], o_cam[1], o_cam[2], 1.0f };
    float d4[4] = { d_cam[0], d_cam[1], d_cam[2], 0.0f };
    m3g_transform_point(o_world, &cam_world, o4);
    m3g_transform_point(d_world, &cam_world, d4);

    /* 4. World -> this Group's coordinate system (inverse composite) */
    M3GTransform grp_world, grp_inv;
    m3g_node_world_and_parent(group, &grp_world, NULL);
    if (!m3g_transform_invert(&grp_inv, &grp_world)) {
        /* spec: singular node transforms may cause ArithmeticException;
         * report "no hit" rather than crashing the game */
        return NATIVE_RETURN_INT(0);
    }
    float o_grp[4], d_grp[4];
    m3g_transform_point(o_grp, &grp_inv, o_world);
    m3g_transform_point(d_grp, &grp_inv, d_world);

    /* 5. delegate to the Node.pick engine: (node, scope, ox,oy,oz, dx,dy,dz, ri) */
    JavaValue pargs[9];
    memset(pargs, 0, sizeof(pargs));
    pargs[0].ref = (void*)group;
    pargs[1].i = scope;
    pargs[2].f = o_grp[0]; pargs[3].f = o_grp[1]; pargs[4].f = o_grp[2];
    pargs[5].f = d_grp[0]; pargs[6].f = d_grp[1]; pargs[7].f = d_grp[2];
    pargs[8].ref = (void*)ri;
    return native_node_pick(jvm, thread, pargs, 9);
}

/* Legacy (III)Camera form — int coordinates (pre-spec registration that some
 * decompiler-era game code may still call). Wraps the float implementation. */
static JavaValue native_group_pick(JVM* jvm, JavaThread* thread,
                                   JavaValue* args, int arg_count) {
    JavaValue fargs[6];
    memset(fargs, 0, sizeof(fargs));
    fargs[0] = args[0];
    fargs[1] = args[1];
    fargs[2].f = (jfloat)args[2].i;
    fargs[3].f = (jfloat)args[3].i;
    fargs[4] = args[4];
    fargs[5] = args[5];
    return native_group_pick_f(jvm, thread, fargs, arg_count);
}

/* ---- Image2D spec constructors ---- */

/* Image2D.<init>(int format, int width, int height, byte[] pixels) — raw
 * pixels in the given format; mirrors native_image2d_set's converter. */
static JavaValue native_image2d_init_raw_bytes(JVM* jvm, JavaThread* thread,
                                               JavaValue* args, int arg_count) {
    (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    jint format = args[1].i;
    jint width = args[2].i;
    jint height = args[3].i;
    JavaArray* src = (JavaArray*)args[4].ref;

    if (!obj || width <= 0 || height <= 0) return NATIVE_RETURN_VOID();
    if (width > M3G_MAX_IMAGE_DIMENSION || height > M3G_MAX_IMAGE_DIMENSION) return NATIVE_RETURN_VOID();
    jint pixel_count = width * height;
    if (pixel_count > M3G_MAX_IMAGE_PIXELS || pixel_count <= 0) return NATIVE_RETURN_VOID();

    JavaArray* pixels = jvm_new_array(jvm, T_INT, pixel_count, NULL);
    if (!pixels) return NATIVE_RETURN_VOID();
    m3g_set_ref_field(obj, "pixels", (JavaObject*)pixels);
    m3g_set_int_field(obj, "width", width);
    m3g_set_int_field(obj, "height", height);
    m3g_set_int_field(obj, "format", format);

    if (src) {
        /* Reuse Image2D.set() for the conversion (it reads format/width
         * from the object fields we just initialized). */
        JavaValue sargs[6];
        memset(sargs, 0, sizeof(sargs));
        sargs[0].ref = (void*)obj;
        sargs[1].i = 0; sargs[2].i = 0;
        sargs[3].i = width; sargs[4].i = height;
        sargs[5].ref = (void*)src;
        native_image2d_set(jvm, thread, sargs, 6);
    }
    GFX_DEBUG("Image2D.<init>(I,I,I,[B): format=%d %dx%d", format, width, height);
    return NATIVE_RETURN_VOID();
}

/* Image2D.<init>(int format, byte[] encoded) — PNG-encoded bytes. */
static JavaValue native_image2d_init_encoded(JVM* jvm, JavaThread* thread,
                                              JavaValue* args, int arg_count) {
    (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    jint format = args[1].i;
    JavaArray* src = (JavaArray*)args[2].ref;
    if (!obj || !src) return NATIVE_RETURN_VOID();

    extern MidpImage* midp_image_create_from_data(const uint8_t* data, int offset, int length);
    jbyte* data = (jbyte*)array_data(src);
    MidpImage* img = midp_image_create_from_data((const uint8_t*)data, 0, (int)src->length);
    if (!img) {
        /* spec: IllegalArgumentException on undecodable data */
        return NATIVE_RETURN_VOID();
    }

    jint pixel_count = img->width * img->height;
    if (pixel_count <= 0 || pixel_count > M3G_MAX_IMAGE_PIXELS) return NATIVE_RETURN_VOID();
    JavaArray* pixels = jvm_new_array(jvm, T_INT, pixel_count, NULL);
    if (!pixels) return NATIVE_RETURN_VOID();
    jint* dst = (jint*)array_data(pixels);
    for (int i = 0; i < pixel_count; i++) dst[i] = (jint)img->pixels[i];

    m3g_set_ref_field(obj, "pixels", (JavaObject*)pixels);
    m3g_set_int_field(obj, "width", img->width);
    m3g_set_int_field(obj, "height", img->height);
    m3g_set_int_field(obj, "format", format);
    GFX_DEBUG("Image2D.<init>(I,[B): decoded %dx%d", img->width, img->height);
    return NATIVE_RETURN_VOID();
}

