static JavaValue native_rayintersection_getTexture_f(JVM* jvm, JavaThread* thread,
                                                      JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* ri = (JavaObject*)args[0].ref;
    JavaArray* out = (JavaArray*)args[1].ref;
    if (!ri || !out || out->element_type != T_FLOAT || out->length < 2) {
        return NATIVE_RETURN_FLOAT(0.0f);
    }
    jfloat* d = (jfloat*)array_data(out);
    d[0] = d[1] = 0.0f;
    JavaArray* s = (JavaArray*)m3g_get_ref_field(ri, "textureS");
    JavaArray* t = (JavaArray*)m3g_get_ref_field(ri, "textureT");
    if (s && s->element_type == T_FLOAT && s->length > 0) d[0] = ((jfloat*)array_data(s))[0];
    if (t && t->element_type == T_FLOAT && t->length > 0) d[1] = ((jfloat*)array_data(t))[0];
    return NATIVE_RETURN_FLOAT(m3g_get_float_field(ri, "distance", 0.0f));
}

/* ---- SkinnedMesh spec API ---- */

/* addTransform(Node, int first, int count, float weight) — the FLOAT weight
 * is stored scaled x100 into the int[] boneWeights field: the blending math
 * divides by the weight SUM, so any consistent scale preserves ratios
 * (0.5/0.5 -> 50/50, 0.7/0.3 -> 70/30). */
static JavaValue native_skinnedmesh_addTransform_f(JVM* jvm, JavaThread* thread,
                                                    JavaValue* args, int arg_count) {
    (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    JavaObject* bone = (JavaObject*)args[1].ref;
    jint first = args[2].i, count = args[3].i;
    jfloat weight = args[4].f;
    if (!sm || !bone) return NATIVE_RETURN_VOID();

    JavaArray* refs  = (JavaArray*)m3g_get_ref_field(sm, "boneNodeRefs");
    JavaArray* firsta= (JavaArray*)m3g_get_ref_field(sm, "boneFirstVertex");
    JavaArray* cnta  = (JavaArray*)m3g_get_ref_field(sm, "boneVertexCount");
    JavaArray* wgta  = (JavaArray*)m3g_get_ref_field(sm, "boneWeights");
    /* create the binding arrays on first addTransform (the spec ctor only
     * wires VB/IB/Appearance/skeleton — bones arrive exclusively here) */
    if (!refs)  { refs  = jvm_new_array(jvm, DESC_OBJECT, 0, NULL); m3g_set_ref_field(sm, "boneNodeRefs", (JavaObject*)refs); }
    if (!firsta){ firsta= jvm_new_array(jvm, T_INT, 0, NULL); m3g_set_ref_field(sm, "boneFirstVertex", (JavaObject*)firsta); }
    if (!cnta)  { cnta  = jvm_new_array(jvm, T_INT, 0, NULL); m3g_set_ref_field(sm, "boneVertexCount", (JavaObject*)cnta); }
    if (!wgta)  { wgta  = jvm_new_array(jvm, T_INT, 0, NULL); m3g_set_ref_field(sm, "boneWeights", (JavaObject*)wgta); }
    if (!refs || !firsta || !cnta || !wgta) return NATIVE_RETURN_VOID();

    int old = refs->length;
    JavaArray* nrefs  = jvm_new_array(jvm, DESC_OBJECT, old + 1, NULL);
    JavaArray* nfirst = jvm_new_array(jvm, T_INT, old + 1, NULL);
    JavaArray* ncnt   = jvm_new_array(jvm, T_INT, old + 1, NULL);
    JavaArray* nwgt   = jvm_new_array(jvm, T_INT, old + 1, NULL);
    if (!nrefs || !nfirst || !ncnt || !nwgt) return NATIVE_RETURN_VOID();
    if (old) {
        memcpy(array_data(nrefs),  array_data(refs),  (size_t)old * sizeof(void*));
        memcpy(array_data(nfirst), array_data(firsta),(size_t)old * sizeof(jint));
        memcpy(array_data(ncnt),   array_data(cnta),  (size_t)old * sizeof(jint));
        memcpy(array_data(nwgt),   array_data(wgta),  (size_t)old * sizeof(jint));
    }
    ((JavaObject**)array_data(nrefs))[old] = bone;
    ((jint*)array_data(nfirst))[old] = first;
    ((jint*)array_data(ncnt))[old] = count;
    jint w_int = (jint)(weight * 100.0f);
    if (w_int < 0) w_int = 0;
    ((jint*)array_data(nwgt))[old] = w_int;
    m3g_set_ref_field(sm, "boneNodeRefs", (JavaObject*)nrefs);
    m3g_set_ref_field(sm, "boneFirstVertex", (JavaObject*)nfirst);
    m3g_set_ref_field(sm, "boneVertexCount", (JavaObject*)ncnt);
    m3g_set_ref_field(sm, "boneWeights", (JavaObject*)nwgt);
    return NATIVE_RETURN_VOID();
}

