/* getBoneTransform(int index, Transform) */
static JavaValue native_skinnedmesh_getBoneTransform_idx(JVM* jvm, JavaThread* thread,
                                                          JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    jint index = args[1].i;
    JavaObject* transform = (JavaObject*)args[2].ref;
    if (!sm || !transform) return NATIVE_RETURN_VOID();
    JavaArray* refs = (JavaArray*)m3g_get_ref_field(sm, "boneNodeRefs");
    if (!refs || index < 0 || index >= (jint)refs->length) return NATIVE_RETURN_VOID();
    JavaObject* bone = ((JavaObject**)array_data(refs))[index];
    if (!bone) return NATIVE_RETURN_VOID();
    M3GTransform t;
    m3g_build_node_transform(bone, &t);
    set_native_transform(transform, &t);
    return NATIVE_RETURN_VOID();
}

