/* getBoneVertices(int index, int[] vertices, float[] weights) */
static JavaValue native_skinnedmesh_getBoneVertices(JVM* jvm, JavaThread* thread,
                                                     JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    jint index = args[1].i;
    JavaArray* verts = (JavaArray*)args[2].ref;
    JavaArray* weights = (JavaArray*)args[3].ref;
    if (!sm || !verts || !weights) return NATIVE_RETURN_VOID();

    JavaArray* firsta = (JavaArray*)m3g_get_ref_field(sm, "boneFirstVertex");
    JavaArray* cnta   = (JavaArray*)m3g_get_ref_field(sm, "boneVertexCount");
    JavaArray* wgta   = (JavaArray*)m3g_get_ref_field(sm, "boneWeights");
    if (!firsta || !cnta || !wgta || index < 0 || index >= (jint)firsta->length)
        return NATIVE_RETURN_VOID();

    jint first = ((jint*)array_data(firsta))[index];
    jint count = ((jint*)array_data(cnta))[index];
    jint wraw  = ((jint*)array_data(wgta))[index];
    jfloat w = wraw > 0 ? (jfloat)wraw / 100.0f : 1.0f;

    jint* vd = (jint*)array_data(verts);
    jfloat* wd = (jfloat*)array_data(weights);
    int n = (int)verts->length < (int)weights->length ? (int)verts->length : (int)weights->length;
    if (n > count) n = count;
    for (int i = 0; i < n; i++) {
        vd[i] = first + i;
        wd[i] = w;
    }
    return NATIVE_RETURN_VOID();
}

