/* ---- Transform.transform(VertexArray in, float[] out, boolean W) — javadoc:
 * "Multiplies the elements of the given VertexArray with this matrix,
 * storing the transformed values in a float array... The input may have any
 * number of elements (E), two or three components per element (C), and any
 * component size (8 or 16 bit). The float array is filled in with E elements,
 * each having four components. The multiplication is always done with a full
 * 4x4 matrix and all four components of the result are returned." If W is
 * true the input W component is 1.0, else 0.0; 2-component inputs get Z=0.
 * No scale/bias applied (those live in VertexBuffer). No division by W.
 * Column-vector convention: out = M * v. ---- */
static JavaValue native_transform_transform_va(JVM* jvm, JavaThread* thread,
                                               JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    JavaObject* in_va = (JavaObject*)args[1].ref;
    JavaArray* out = (JavaArray*)args[2].ref;
    jint w_flag = args[3].i;
    if (!obj || !in_va || !out) return NATIVE_RETURN_VOID();
    if (out->element_type != T_FLOAT) return NATIVE_RETURN_VOID();

    JavaArray* data = (JavaArray*)m3g_get_ref_field(in_va, "data");
    jint comps = m3g_get_int_field(in_va, "componentCount", 0);
    jint count = m3g_get_int_field(in_va, "vertexCount", 0);
    if (!data || comps < 2 || comps > 4 || count <= 0) return NATIVE_RETURN_VOID();

    M3GTransform* t = get_native_transform(obj);
    if (!t) return NATIVE_RETURN_VOID();

    jfloat* dst = (jfloat*)array_data(out);
    jsize capacity = out->length / 4;   /* E elements x 4 components each */
    int n = (count < capacity) ? (int)count : (int)capacity;

    float w_in = w_flag ? 1.0f : 0.0f;
    if (data->element_type == T_FLOAT) {
        jfloat* s = (jfloat*)array_data(data);
        for (int i = 0; i < n; i++) {
            float v[4] = { s[i*comps], (comps > 1 ? s[i*comps+1] : 0.0f),
                           (comps > 2 ? s[i*comps+2] : 0.0f), w_in };
            m3g_transform_point(&dst[i*4], t, v);
        }
    } else if (data->element_type == T_SHORT) {
        int16_t* s = (int16_t*)array_data(data);
        for (int i = 0; i < n; i++) {
            float v[4] = { (float)s[i*comps], (comps > 1 ? (float)s[i*comps+1] : 0.0f),
                           (comps > 2 ? (float)s[i*comps+2] : 0.0f), w_in };
            m3g_transform_point(&dst[i*4], t, v);
        }
    } else if (data->element_type == T_BYTE) {
        int8_t* s = (int8_t*)array_data(data);
        for (int i = 0; i < n; i++) {
            float v[4] = { (float)s[i*comps], (comps > 1 ? (float)s[i*comps+1] : 0.0f),
                           (comps > 2 ? (float)s[i*comps+2] : 0.0f), w_in };
            m3g_transform_point(&dst[i*4], t, v);
        }
    }
    return NATIVE_RETURN_VOID();
}

