/* ---- SkinnedMesh.getBoneVertices(Node bone, int[] indices, float[] weights)
 * — javadoc: "Returns the number of vertices influenced by the given bone,
 * filling in the vertices and their weights to the given arrays. If either
 * or both of the arrays are null, only the number of vertices is returned.
 * ... Duplicate indices and indices with zero weight are not returned. The
 * returned weights are normalized so that all weights (from all contributing
 * bones) corresponding to a single vertex sum to one."
 * Bones live in TWO storages: the spec addTransform() path builds
 * "boneNodeRefs"/"boneFirstVertex"/"boneVertexCount"/"boneWeights"; the M3G
 * file loader fills "bones" with the same index/count companions. Match the
 * given Node across both (they hold the same bone at most once per range
 * entry — multiple ranges per bone are legal). ---- */
static JavaValue native_skinnedmesh_getBoneVertices_node(JVM* jvm, JavaThread* thread,
                                                         JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    JavaObject* bone = (JavaObject*)args[1].ref;
    JavaArray* indices = (JavaArray*)args[2].ref;
    JavaArray* weights = (JavaArray*)args[3].ref;
    if (!sm || !bone) return NATIVE_RETURN_INT(0);

    JavaArray* refs = (JavaArray*)m3g_get_ref_field(sm, "boneNodeRefs");
    if (!refs || refs->element_type != DESC_OBJECT) {
        /* file-loaded skeleton bindings */
        refs = (JavaArray*)m3g_get_ref_field(sm, "bones");
    }
    JavaArray* firsta = (JavaArray*)m3g_get_ref_field(sm, "boneFirstVertex");
    JavaArray* cnta = (JavaArray*)m3g_get_ref_field(sm, "boneVertexCount");
    JavaArray* wgta = (JavaArray*)m3g_get_ref_field(sm, "boneWeights");
    if (!refs || !firsta || !cnta) return NATIVE_RETURN_INT(0);

    jsize nb = refs->length;
    JavaObject** bone_nodes = (JavaObject**)array_data(refs);
    jint* vfirst = (jint*)array_data(firsta);
    jint* vcount = (jint*)array_data(cnta);
    jint* vwgt = (wgta && wgta->element_type == T_INT &&
                  wgta->length >= nb) ? (jint*)array_data(wgta) : NULL;

    /* Pass 1: total influence per vertex across ALL bones (for the spec's
     * normalization rule). Cap the scratch table at a sane size; games
     * never exceed it. */
    jint max_vertex = 0;
    for (jsize i = 0; i < nb; i++) {
        if (bone_nodes[i] && vcount[i] > 0 &&
            vfirst[i] + vcount[i] > max_vertex) max_vertex = vfirst[i] + vcount[i];
    }
    if (max_vertex <= 0 || max_vertex > 1 << 20) return NATIVE_RETURN_INT(0);
    float* totals = (float*)calloc((size_t)max_vertex, sizeof(float));
    if (!totals) return NATIVE_RETURN_INT(0);
    for (jsize i = 0; i < nb; i++) {
        if (!bone_nodes[i]) continue;
        jfloat w = vwgt ? ((jfloat)vwgt[i] / 100.0f) : 1.0f;
        if (vwgt && vwgt[i] <= 0) w = 1.0f;
        for (jint v = vfirst[i]; v < vfirst[i] + vcount[i] && v < max_vertex; v++)
            totals[v] += w;
    }

    /* Pass 2: collect the requested bone's vertices with normalized weights */
    jint written = 0;
    if (indices && weights && indices->element_type == T_INT &&
        weights->element_type == T_FLOAT) {
        jint* idst = (jint*)array_data(indices);
        jfloat* wdst = (jfloat*)array_data(weights);
        jsize cap = indices->length < weights->length ? indices->length : weights->length;
        for (jsize i = 0; i < nb && written < (jint)cap; i++) {
            if (bone_nodes[i] != bone) continue;
            jfloat w = vwgt ? ((jfloat)vwgt[i] / 100.0f) : 1.0f;
            if (vwgt && vwgt[i] <= 0) w = 1.0f;
            for (jint v = vfirst[i]; v < vfirst[i] + vcount[i] && v < max_vertex; v++) {
                if (written >= (jint)cap) break;
                if (w <= 0.0f) continue;               /* zero weight not returned */
                idst[written] = v;
                wdst[written] = totals[v] > 1e-6f ? w / totals[v] : w;
                written++;
            }
        }
    } else {
        /* null arrays: only the count (spec) */
        for (jsize i = 0; i < nb; i++) {
            if (bone_nodes[i] != bone) continue;
            written += vcount[i];
        }
    }
    free(totals);
    return NATIVE_RETURN_INT(written);
}

/* ---- MorphingMesh.getWeights(float[] weights) — javadoc: void return,
 * "array to be populated with the morph target weights". The registered
 * ([F)I variant is kept for older game code that reads the count. ---- */
static JavaValue native_morph_getWeights_void(JVM* jvm, JavaThread* thread,
                                              JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* m = (JavaObject*)args[0].ref;
    JavaArray* dst = (JavaArray*)args[1].ref;
    if (m && dst && dst->element_type == T_FLOAT) {
        JavaArray* w = (JavaArray*)m3g_get_ref_field(m, "morphWeights");
        if (w && w->element_type == T_FLOAT) {
            jfloat* s = (jfloat*)array_data(w);
            jfloat* d = (jfloat*)array_data(dst);
            int n = w->length < dst->length ? w->length : dst->length;
            for (int i = 0; i < n; i++) d[i] = s[i];
        }
    }
    return NATIVE_RETURN_VOID();
}

/* ---- IndexBuffer.getIndices(int[] indices) — javadoc: void return, "the
 * array to populate with the vertex indices". The registered ([I)I variant
 * stays for compat. ---- */
static JavaValue native_indexbuffer_getIndices_void(JVM* jvm, JavaThread* thread,
                                                    JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* ib = (JavaObject*)args[0].ref;
    JavaArray* out = (JavaArray*)args[1].ref;
    if (!ib || !out || out->element_type != T_INT) return NATIVE_RETURN_VOID();
    JavaArray* indices = (JavaArray*)m3g_get_ref_field(ib, "indices");
    if (!indices) return NATIVE_RETURN_VOID();
    int n = (int)indices->length;
    if (n > (int)out->length) n = (int)out->length;
    jint* dst = (jint*)array_data(out);
    if (indices->element_type == T_SHORT) {
        int16_t* sd = (int16_t*)array_data(indices);
        for (int i = 0; i < n; i++) dst[i] = sd[i];
    } else if (indices->element_type == T_INT) {
        jint* sd = (jint*)array_data(indices);
        for (int i = 0; i < n; i++) dst[i] = sd[i];
    } else if (indices->element_type == T_BYTE) {
        int8_t* sd = (int8_t*)array_data(indices);
        for (int i = 0; i < n; i++) dst[i] = sd[i];
    }
    return NATIVE_RETURN_VOID();
}

/* ---- Image2D.<init>(int format, int width, int height, byte[] image,
 * byte[] palette) — javadoc: "Each pixel is composed of one byte,
 * representing a palette index. The palette consists of 256 entries, all
 * with the same number of color components... If the array has N entries,
 * N < 256, the remaining entries [N, 255] are left undefined." Conversion to
 * the internal ARGB pixel array mirrors Image2D.set per-format semantics. ---- */
static JavaValue native_image2d_init_palette(JVM* jvm, JavaThread* thread,
                                             JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    jint format = args[1].i;
    jint width = args[2].i;
    jint height = args[3].i;
    JavaArray* src = (JavaArray*)args[4].ref;
    JavaArray* pal = (JavaArray*)args[5].ref;

    if (!obj || !src || !pal) return NATIVE_RETURN_VOID();
    if (width <= 0 || height <= 0) return NATIVE_RETURN_VOID();
    if (width > M3G_MAX_IMAGE_DIMENSION || height > M3G_MAX_IMAGE_DIMENSION) return NATIVE_RETURN_VOID();
    jint pixel_count = width * height;
    if (pixel_count > M3G_MAX_IMAGE_PIXELS || pixel_count <= 0) return NATIVE_RETURN_VOID();
    if ((jsize)src->length < pixel_count) return NATIVE_RETURN_VOID();  /* spec: image.length < width*height */

    int cpp;
    switch (format) {
        case 100: cpp = 4; break;              /* RGBA */
        case 99:  cpp = 3; break;              /* RGB */
        case 98:  cpp = 2; break;              /* LUMINANCE_ALPHA */
        case 97:  cpp = 1; break;              /* LUMINANCE */
        case 96:  cpp = 1; break;              /* ALPHA */
        default:  cpp = 0; break;              /* invalid format: leave zeros */
    }
    if (cpp == 0) return NATIVE_RETURN_VOID();

    /* spec: palette.length % C == 0 (when < 256*C) */
    jsize pal_entries = pal->length / cpp;

    JavaArray* pixels = jvm_new_array(jvm, T_INT, pixel_count, NULL);
    if (!pixels) return NATIVE_RETURN_VOID();
    m3g_set_ref_field(obj, "pixels", (JavaObject*)pixels);
    m3g_set_int_field(obj, "width", width);
    m3g_set_int_field(obj, "height", height);
    m3g_set_int_field(obj, "format", format);

    uint8_t* sd = (uint8_t*)array_data(src);
    uint8_t* pd = (uint8_t*)array_data(pal);
    uint32_t* dst = (uint32_t*)array_data(pixels);
    for (jint i = 0; i < pixel_count; i++) {
        uint32_t idx = sd[i];
        uint32_t out = 0xFF000000u;  /* undefined palette entries: opaque */
        if (idx < (uint32_t)pal_entries) {
            const uint8_t* e = pd + (size_t)idx * cpp;
            switch (format) {
            case 99:  /* RGB */
                out = 0xFF000000u | ((uint32_t)e[0] << 16) | ((uint32_t)e[1] << 8) | e[2];
                break;
            case 100: /* RGBA */
                out = ((uint32_t)e[3] << 24) | ((uint32_t)e[0] << 16) | ((uint32_t)e[1] << 8) | e[2];
                break;
            case 98: { /* LUMINANCE_ALPHA */
                uint32_t v = e[0];
                out = ((uint32_t)e[1] << 24) | (v << 16) | (v << 8) | v;
                break; }
            case 97: { /* LUMINANCE */
                uint32_t v = e[0];
                out = 0xFF000000u | (v << 16) | (v << 8) | v;
                break; }
            case 96:  /* ALPHA */
                out = ((uint32_t)e[0] << 24) | 0x00FFFFFFu;
                break;
            }
        }
        dst[i] = out;
    }
    GFX_DEBUG("Image2D.<init>(I,I,I,[B,[B): palette fmt=%d %dx%d entries=%d",
              format, width, height, (int)pal_entries);
    return NATIVE_RETURN_VOID();
}

