/* ---- Texture2D Transformable completion ---- */
static JavaValue native_texture2d_getTransform(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* tex = (JavaObject*)args[0].ref;
    JavaObject* transform = (JavaObject*)args[1].ref;
    if (!tex || !transform) return NATIVE_RETURN_VOID();
    M3GTransform t;
    m3g_transform_identity(&t);
    JavaArray* arr = (JavaArray*)m3g_get_ref_field(tex, "transform");
    if (arr && arr->element_type == T_FLOAT && arr->length >= 16) {
        memcpy(t.m, array_data(arr), 16 * sizeof(float));
    }
    set_native_transform(transform, &t);
    return NATIVE_RETURN_VOID();
}

static JavaValue native_texture2d_setImage(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* tex = (JavaObject*)args[0].ref;
    JavaObject* image = (JavaObject*)args[1].ref;
    if (!tex) return NATIVE_RETURN_VOID();
    /* TEMP-DIAG: log setImage calls with image info */
    {
        static int cnt = 0;
        if (cnt < 40) {
            cnt++;
            int w = image ? m3g_get_int_field(image, "width", -1) : -1;
            int h = image ? m3g_get_int_field(image, "height", -1) : -1;
            JavaFrame* cf = (thread && thread->current_frame) ? thread->current_frame : NULL;
            LOG_SAFE("[SETIMG] #%d tex=%p image=%p %dx%d caller=%s.%s\n", cnt, (void*)tex, (void*)image,
                     w, h,
                     (cf && cf->clazz && cf->clazz->class_name) ? cf->clazz->class_name : "?",
                     (cf && cf->method && cf->method->name) ? cf->method->name : "?");
        }
    }
    m3g_set_ref_field(tex, "image", image);
    /* v36 FIX (Asphalt 3 3D — white road/car textures): setImage must also
     * refresh the C-side tex-image map (tier-1 lookup in m3g_build_texture2d).
     * The map was only written by Texture2D.<init> — the constructor-time
     * image (Asphalt: the 8x8 white placeholder l.b) — so the FIRST build of
     * a texture that was later re-pointed via setImage resolved the STALE
     * image and rendered as an 8x8 white quad. The cache-invalidation below
     * only helps textures that were already built once; textures built AFTER
     * setImage (the normal Asphalt flow: meshes parsed -> lazy PNG loader
     * setImage -> first render at race start) went through tier-1 and never
     * saw the new image. JSR-184 Texture2D.setImage: the new image is used
     * for all subsequent rendering. */
    if (image) {
        m3g_store_tex_image_map(tex, image);
    } else {
        /* setImage(null): drop the tier-1 mapping so later builds fall
         * through to the Java "image" field (which we just set to null). */
        for (int i = 0; i < g_m3g_tex_image_map_count; i++) {
            if (g_m3g_tex_image_map[i].texture_obj == tex) {
                g_m3g_tex_image_map[i].image_obj = NULL;
                break;
            }
        }
    }
    /* Invalidate the built texture so the next render re-uploads pixels */
    M3GTexture2D* built = m3g_lookup_texture_cache(tex);
    if (built) {
        built->source_image = image;
        built->generation = 0;  /* force refresh on next use */
    }
    return NATIVE_RETURN_VOID();
}

static JavaValue native_texture2d_getImage(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* tex = (JavaObject*)args[0].ref;
    return NATIVE_RETURN_OBJECT(tex ? m3g_get_ref_field(tex, "image") : NULL);
}

