static JavaValue native_g3d_getCamera(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    /* v30: the Graphics3D stub has no "camera" field — the old lookup always
     * returned null. The current camera is tracked in g_m3g (setCamera). */
    if (g_m3g.camera && !heap_java_object_valid(g_m3g.camera)) {
        g_m3g.camera = NULL;
        g_m3g.camera_set = 0;
    }
    /* JSR-184: fills the Transform with the camera's WORLD transform. */
    {
        JavaObject* transform = (JavaObject*)args[1].ref;
        if (transform && g_m3g.camera_set) {
            set_native_transform(transform, &g_m3g.camera_transform);
        } else if (transform) {
            M3GTransform identity;
            m3g_transform_identity(&identity);
            set_native_transform(transform, &identity);
        }
    }
    return NATIVE_RETURN_OBJECT(g_m3g.camera);
}
