static JavaValue native_vb_getPositions(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* vb = (JavaObject*)args[0].ref;
    JavaArray* scale = (JavaArray*)args[1].ref;
    if (vb && scale && scale->element_type == T_FLOAT) {
        /* v30: JSR-184 scaleBias = { scale, biasX, biasY, biasZ } — the old
         * code wrote only the scale element. */
        jfloat* sb = (jfloat*)array_data(scale);
        if (scale->length >= 1) sb[0] = m3g_get_float_field(vb, "positionScale", 1.0f);
        if (scale->length >= 2) sb[1] = m3g_get_float_field(vb, "biasX", 0.0f);
        if (scale->length >= 3) sb[2] = m3g_get_float_field(vb, "biasY", 0.0f);
        if (scale->length >= 4) sb[3] = m3g_get_float_field(vb, "biasZ", 0.0f);
    }
    return NATIVE_RETURN_OBJECT(vb ? m3g_get_ref_field(vb, "positions") : NULL);
}
static JavaValue native_vb_getTexCoords(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* vb = (JavaObject*)args[0].ref;
    jint index = args[1].i;
    JavaArray* scale = (JavaArray*)args[2].ref;
    if (!vb) return NATIVE_RETURN_NULL();
    if (index == 0 || index == 1) {
        /* v30: spec scaleBias = { scale, biasX, biasY, 0 }; unit-1 supported. */
        if (scale && scale->element_type == T_FLOAT) {
            jfloat* sb = (jfloat*)array_data(scale);
            if (scale->length >= 1) sb[0] = m3g_get_float_field(vb, index ? "texCoordScale1" : "texCoordScale", 1.0f);
            if (scale->length >= 2) sb[1] = m3g_get_float_field(vb, index ? "texCoordBiasX1" : "texCoordBiasX", 0.0f);
            if (scale->length >= 3) sb[2] = m3g_get_float_field(vb, index ? "texCoordBiasY1" : "texCoordBiasY", 0.0f);
            if (scale->length >= 4) sb[3] = 0.0f;
        }
        return NATIVE_RETURN_OBJECT(m3g_get_ref_field(vb, index ? "texCoords1" : "texCoords"));
    }
    return NATIVE_RETURN_NULL();
}
