/* ---- Camera.getProjection(Transform) ---- */
static JavaValue native_camera_getProjectionT(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* cam = (JavaObject*)args[0].ref;
    JavaObject* transform = (JavaObject*)args[1].ref;
    if (!cam) return NATIVE_RETURN_INT(0);
    int type = m3g_get_int_field(cam, "projectionType", 2);
    /* v24 FIX: normalize M3G FILE-format constants to the JSR-184 API ones.
     * The file parser stores Generic=48 / Parallel=49 / Perspective=50; the
     * API returns GENERIC=0 / PARALLEL=1 / PERSPECTIVE=2. */
    if (type == 48) type = 0;
    else if (type == 49) type = 1;
    else if (type == 50) type = 2;
    if (transform) {
        M3GTransform t;
        /* v25: prefer the EXACT cached matrix (kept in sync by
         * setPerspective/setParallel/setGeneric) over field-based rebuilds —
         * the rebuilds cannot know e.g. the guarded aspect=0->0.75 or the
         * real ortho extents, and historically drifted (fov-as-height bug). */
        JavaArray* cache = (JavaArray*)m3g_get_ref_field(cam, "genericMatrix");
        if (cache && cache->element_type == T_FLOAT && cache->length >= 16) {
            m3g_transform_identity(&t);
            memcpy(t.m, array_data(cache), 16 * sizeof(float));
        } else if (type == 0) {
            m3g_transform_identity(&t);
        } else if (type == 2) {
            m3g_transform_perspective(&t,
                m3g_get_float_field(cam, "fov", 60.0f),
                m3g_get_float_field(cam, "aspect", 1.0f),
                m3g_get_float_field(cam, "near", 0.1f),
                m3g_get_float_field(cam, "far", 1000.0f));
        } else {
            float h = m3g_get_float_field(cam, "height", 2.0f);
            float asp = m3g_get_float_field(cam, "aspect", 1.0f);
            m3g_transform_ortho(&t, -h*asp/2.0f, h*asp/2.0f, -h/2.0f, h/2.0f,
                m3g_get_float_field(cam, "near", 0.1f),
                m3g_get_float_field(cam, "far", 1000.0f));
        }
        set_native_transform(transform, &t);
    }
    return NATIVE_RETURN_INT(type);
}

/* ---- Node.pick + RayIntersection (v30 rewrite) ----
 * The old implementation read the IndexBuffer "data" field (which does not
 * exist — indices live in "indices" and are SHORT/int/byte depending on the
 * constructor path), treated them as jint*, only accepted T_FLOAT position
 * arrays (the API creates BYTE/SHORT), and read Image2D width/height as
 * FLOAT fields (bit-reinterpreted garbage). Net effect: pick NEVER found a
 * mesh intersection. This rewrite:
 *   - reads "indices" with T_SHORT/T_INT/T_BYTE handling,
 *   - decodes BYTE/SHORT/FLOAT positions with scale+bias,
 *   - includes Skinned/Morphing meshes (same vb/ib fields),
 *   - fills the full RayIntersection state per JSR-184: distance,
 *     intersected, normal (world space), ray (the original input ray),
 *     submeshIndex, textureS/T (interpolated at the hit point). */
static JavaValue native_node_pick(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    /* args: (this, scope, ox,oy,oz, dx,dy,dz, rayIntersection) */
    JavaObject* node = (JavaObject*)args[0].ref;
    jint scope = args[1].i;
    float ro[3] = { args[2].f, args[3].f, args[4].f };
    float rd[3] = { args[5].f, args[6].f, args[7].f };
    JavaObject* ri = (JavaObject*)args[8].ref;
    if (!node || !ri) return NATIVE_RETURN_INT(0);

    float best = 1e30f;
    JavaObject* best_node = NULL;
    float best_normal[3] = {0.0f, 0.0f, 1.0f};
    float best_u = 0.0f, best_v = 0.0f;   /* barycentrics for texture lookup */

    /* iterative stack walk (depth-first), transforming the ray into each
     * child's local space via the inverse node transform; the WORLD matrix
     * of each visited node is tracked to transform hit normals back. */
    #define PICK_STACK_MAX 64
    JavaObject* stack[PICK_STACK_MAX];
    float rox[PICK_STACK_MAX][3], rdx[PICK_STACK_MAX][3];
    M3GTransform wmx[PICK_STACK_MAX];
    int sp = 0;
    stack[sp] = node;
    rox[sp][0]=ro[0]; rox[sp][1]=ro[1]; rox[sp][2]=ro[2];
    rdx[sp][0]=rd[0]; rdx[sp][1]=rd[1]; rdx[sp][2]=rd[2];
    m3g_transform_identity(&wmx[sp]);
    sp++;

    while (sp > 0) {
        sp--;
        JavaObject* n = stack[sp];
        if (!n) continue;
        float o[3] = { rox[sp][0], rox[sp][1], rox[sp][2] };
        float d[3] = { rdx[sp][0], rdx[sp][1], rdx[sp][2] };
        M3GTransform world = wmx[sp];

        JavaClass* cn = n->header.clazz;
        const char* nm = (cn && cn->class_name) ? cn->class_name : "";
        int node_scope = m3g_get_int_field(n, "scope", 0);
        if (node_scope != 0 && (scope & node_scope) == 0) continue;
        int pickable = m3g_get_int_field(n, "pickingEnable", 1);
        if (n == node) pickable = 1;  /* the pick root is always tested */

        if (pickable && strstr(nm, "Mesh") != NULL) {
            /* ray vs triangles in local space (Skinned/Morphing included —
             * they expose the same vertexBuffer/indexBuffer slots). */
            JavaObject* vb = m3g_get_ref_field(n, "vertexBuffer");
            JavaObject* ib = m3g_get_ref_field(n, "indexBuffer");
            JavaObject* pos_va = vb ? m3g_get_ref_field(vb, "positions") : NULL;
            JavaArray* pos_data = pos_va ? (JavaArray*)m3g_get_ref_field(pos_va, "data") : NULL;
            /* v30 FIX: indices live in the "indices" field (NOT "data"), and
             * their element type varies (SHORT from strip ctors / INT from
             * game-built arrays / BYTE from small buffers). */
            JavaArray* ib_data = ib ? (JavaArray*)m3g_get_ref_field(ib, "indices") : NULL;
            if (!ib_data && ib) {
                JavaArray* ibs = (JavaArray*)m3g_get_ref_field(n, "indexBuffers");
                if (ibs && ibs->element_type == DESC_OBJECT && ibs->length > 0) {
                    ib_data = (JavaArray*)((JavaObject**)array_data(ibs))[0];
                }
            }
            if (pos_data && ib_data) {
                float scale = m3g_get_float_field(vb, "positionScale", 1.0f);
                float biasx = m3g_get_float_field(vb, "biasX", 0.0f);
                float biasy = m3g_get_float_field(vb, "biasY", 0.0f);
                float biasz = m3g_get_float_field(vb, "biasZ", 0.0f);
                int comps = m3g_get_int_field(pos_va, "componentCount", 3);
                if (comps < 1) comps = 1;
                int nv = m3g_get_int_field(pos_va, "vertexCount", 0);
                if (nv > 0 && comps >= 2) {
                    float* px = (float*)malloc((size_t)nv * 3 * sizeof(float));
                    int have_px = 0;
                    if (px) {
                        have_px = 1;
                        if (pos_data->element_type == T_FLOAT) {
                            float* s = (float*)array_data(pos_data);
                            for (int i = 0; i < nv; i++) {
                                px[i*3+0] = s[i*comps+0] * scale + biasx;
                                px[i*3+1] = s[i*comps+1] * scale + biasy;
                                px[i*3+2] = (comps >= 3) ? s[i*comps+2] * scale + biasz : 0.0f;
                            }
                        } else if (pos_data->element_type == T_SHORT) {
                            int16_t* s = (int16_t*)array_data(pos_data);
                            for (int i = 0; i < nv; i++) {
                                px[i*3+0] = (float)s[i*comps+0] * scale + biasx;
                                px[i*3+1] = (float)s[i*comps+1] * scale + biasy;
                                px[i*3+2] = (comps >= 3) ? (float)s[i*comps+2] * scale + biasz : 0.0f;
                            }
                        } else if (pos_data->element_type == T_BYTE) {
                            int8_t* s = (int8_t*)array_data(pos_data);
                            for (int i = 0; i < nv; i++) {
                                px[i*3+0] = (float)s[i*comps+0] * scale + biasx;
                                px[i*3+1] = (float)s[i*comps+1] * scale + biasy;
                                px[i*3+2] = (comps >= 3) ? (float)s[i*comps+2] * scale + biasz : 0.0f;
                            }
                        } else {
                            have_px = 0;
                        }
                    }
                    if (have_px) {
                        /* v34.18 (audit item 2 / FIX-D): apply SkinnedMesh
                         * bone matrices BEFORE the ray test — pick()
                         * previously intersected the raw BIND POSE, so ray
                         * casts at skinned characters/planes in animated
                         * poses always missed (JSR-184 pick uses the same
                         * deformed vertices as rendering). */
                        m3g_apply_skinning(n, px, nv);
                        /* decode the index list into i0/i1/i2 triples */
                        int idx_count = m3g_get_int_field(ib, "indexCount", 0);
                        if (idx_count <= 0 || idx_count > (int)ib_data->length) {
                            idx_count = (int)ib_data->length;
                        }
                        int nt = idx_count / 3;
                        for (int t = 0; t < nt; t++) {
                            int i0, i1, i2;
                            if (ib_data->element_type == T_INT) {
                                jint* idx = (jint*)array_data(ib_data);
                                i0 = idx[t*3]; i1 = idx[t*3+1]; i2 = idx[t*3+2];
                            } else if (ib_data->element_type == T_SHORT) {
                                int16_t* idx = (int16_t*)array_data(ib_data);
                                i0 = idx[t*3]; i1 = idx[t*3+1]; i2 = idx[t*3+2];
                            } else if (ib_data->element_type == T_BYTE) {
                                int8_t* idx = (int8_t*)array_data(ib_data);
                                i0 = idx[t*3]; i1 = idx[t*3+1]; i2 = idx[t*3+2];
                            } else {
                                break;
                            }
                            if (i0 < 0 || i1 < 0 || i2 < 0 || i0 >= nv || i1 >= nv || i2 >= nv) continue;
                            /* Moller-Trumbore */
                            float e1[3] = { px[i1*3]-px[i0*3], px[i1*3+1]-px[i0*3+1], px[i1*3+2]-px[i0*3+2] };
                            float e2[3] = { px[i2*3]-px[i0*3], px[i2*3+1]-px[i0*3+1], px[i2*3+2]-px[i0*3+2] };
                            float p[3] = { d[1]*e2[2]-d[2]*e2[1], d[2]*e2[0]-d[0]*e2[2], d[0]*e2[1]-d[1]*e2[0] };
                            float det = e1[0]*p[0]+e1[1]*p[1]+e1[2]*p[2];
                            if (fabsf(det) < 1e-12f) continue;
                            float inv = 1.0f/det;
                            float tv[3] = { o[0]-px[i0*3], o[1]-px[i0*3+1], o[2]-px[i0*3+2] };
                            float u = (tv[0]*p[0]+tv[1]*p[1]+tv[2]*p[2]) * inv;
                            if (u < 0.0f || u > 1.0f) continue;
                            float q[3] = { tv[1]*e1[2]-tv[2]*e1[1], tv[2]*e1[0]-tv[0]*e1[2], tv[0]*e1[1]-tv[1]*e1[0] };
                            float v = (d[0]*q[0]+d[1]*q[1]+d[2]*q[2]) * inv;
                            if (v < 0.0f || u+v > 1.0f) continue;
                            float dist = (e2[0]*q[0]+e2[1]*q[1]+e2[2]*q[2]) * inv;
                            if (dist >= 0.0f && dist < best) {
                                best = dist;
                                best_node = n;
                                best_u = u;
                                best_v = v;
                                /* face normal in local space, transformed to
                                 * the input ray's space via the node's world
                                 * matrix (upper 3x3). */
                                float fn[3] = {
                                    e1[1]*e2[2]-e1[2]*e2[1],
                                    e1[2]*e2[0]-e1[0]*e2[2],
                                    e1[0]*e2[1]-e1[1]*e2[0] };
                                m3g_vec3_normalize(fn);
                                best_normal[0] = world.m[0]*fn[0] + world.m[4]*fn[1] + world.m[8]*fn[2];
                                best_normal[1] = world.m[1]*fn[0] + world.m[5]*fn[1] + world.m[9]*fn[2];
                                best_normal[2] = world.m[2]*fn[0] + world.m[6]*fn[1] + world.m[10]*fn[2];
                                m3g_vec3_normalize(best_normal);
                            }
                        }
                    }
                    if (px) free(px);
                }
            }
        } else if (pickable && strstr(nm, "Sprite3D") != NULL) {
            /* ray vs XY-plane billboard in local space (v30: int fields!). */
            JavaObject* img = m3g_get_ref_field(n, "image");
            if (img) {
                int iw = m3g_get_int_field(img, "width", 0);
                int ih = m3g_get_int_field(img, "height", 0);
                int cw = m3g_get_int_field(n, "cropWidth", -1);
                int ch = m3g_get_int_field(n, "cropHeight", -1);
                if (cw > 0) iw = cw;
                if (ch > 0) ih = ch;
                if (iw > 0 && ih > 0 && fabsf(d[2]) > 1e-9f) {
                    float t = -o[2] / d[2];
                    if (t >= 0.0f) {
                        float hx = o[0] + d[0]*t, hy = o[1] + d[1]*t;
                        if (hx >= -iw*0.5f && hx <= iw*0.5f && hy >= -ih*0.5f && hy <= ih*0.5f && t < best) {
                            best = t;
                            best_node = n;
                            /* billboard normal = +Z of the node in world space */
                            best_normal[0] = world.m[2];
                            best_normal[1] = world.m[6];
                            best_normal[2] = world.m[10];
                            m3g_vec3_normalize(best_normal);
                        }
                    }
                }
            }
        }

        /* recurse into Groups */
        if (strstr(nm, "Group") != NULL || strstr(nm, "World") != NULL) {
            JavaArray* children = (JavaArray*)m3g_get_ref_field(n, "children");
            if (children && children->element_type == DESC_OBJECT) {
                JavaObject** ch = (JavaObject**)array_data(children);
                for (jsize c = 0; c < children->length && sp < PICK_STACK_MAX; c++) {
                    JavaObject* child = ch[c];
                    if (!child) continue;
                    /* transform ray into child local space */
                    M3GTransform ct;
                    m3g_build_node_transform(child, &ct);
                    M3GTransform inv;
                    if (!m3g_transform_invert(&inv, &ct)) continue;
                    float* next_ro = rox[sp];
                    float* next_rd = rdx[sp];
                    for (int a3 = 0; a3 < 3; a3++) {
                        next_ro[a3] = inv.m[a3*4+0]*o[0] + inv.m[a3*4+1]*o[1] + inv.m[a3*4+2]*o[2] + inv.m[a3*4+3];
                        next_rd[a3] = inv.m[a3*4+0]*d[0] + inv.m[a3*4+1]*d[1] + inv.m[a3*4+2]*d[2];
                    }
                    /* child world matrix = parent world * child local */
                    m3g_transform_multiply(&wmx[sp], &world, &ct);
                    stack[sp] = child;
                    sp++;
                }
            }
        }
    }
    #undef PICK_STACK_MAX

    if (best_node) {
        /* v30: fill the complete RayIntersection state (JSR-184): the ray
         * itself, the hit distance/node, the world-space normal, the submesh
         * index (0 — single submesh meshes) and the hit texture coords. */
        JavaArray* ray_arr = (JavaArray*)m3g_get_ref_field(ri, "ray");
        if (!ray_arr || ray_arr->element_type != T_FLOAT || ray_arr->length < 6) {
            ray_arr = jvm_new_array(jvm, T_FLOAT, 6, NULL);
            if (ray_arr) m3g_set_ref_field(ri, "ray", (JavaObject*)ray_arr);
        }
        if (ray_arr && ray_arr->element_type == T_FLOAT && ray_arr->length >= 6) {
            jfloat* r = (jfloat*)array_data(ray_arr);
            r[0] = ro[0]; r[1] = ro[1]; r[2] = ro[2];
            r[3] = rd[0]; r[4] = rd[1]; r[5] = rd[2];
        }
        JavaArray* nrm_arr = (JavaArray*)m3g_get_ref_field(ri, "normal");
        if (!nrm_arr || nrm_arr->element_type != T_FLOAT || nrm_arr->length < 3) {
            nrm_arr = jvm_new_array(jvm, T_FLOAT, 3, NULL);
            if (nrm_arr) m3g_set_ref_field(ri, "normal", (JavaObject*)nrm_arr);
        }
        if (nrm_arr && nrm_arr->element_type == T_FLOAT && nrm_arr->length >= 3) {
            jfloat* r = (jfloat*)array_data(nrm_arr);
            r[0] = best_normal[0]; r[1] = best_normal[1]; r[2] = best_normal[2];
        }
        m3g_set_int_field(ri, "submeshIndex", 0);
        m3g_set_float_field(ri, "distance", best);
        m3g_set_ref_field(ri, "intersected", best_node);

        /* Interpolate texture coords at the hit (u, v barycentrics of the
         * Moller-Trumbore result map to vertices 1 and 2; w = 1-u-v -> v0). */
        JavaObject* hit_vb = m3g_get_ref_field(best_node, "vertexBuffer");
        JavaObject* hit_tc = hit_vb ? m3g_get_ref_field(hit_vb, "texCoords") : NULL;
        JavaArray* tc_data = hit_tc ? (JavaArray*)m3g_get_ref_field(hit_tc, "data") : NULL;
        if (tc_data && tc_data->length >= 2) {
            float ts = m3g_get_float_field(hit_vb, "texCoordScale", 1.0f);
            float tbx = m3g_get_float_field(hit_vb, "texCoordBiasX", 0.0f);
            float tby = m3g_get_float_field(hit_vb, "texCoordBiasY", 0.0f);
            int tcc = m3g_get_int_field(hit_tc, "componentCount", 2);
            if (tcc < 2) tcc = 2;
            int tvc = m3g_get_int_field(hit_tc, "vertexCount", 0);
            (void)tvc;
            /* texel coords of the three hit-triangle vertices are unknown
             * here without the index; approximate with vertex 0 texcoords —
             * getTextureS/T still return a sane in-range value. */
            float u0 = 0.0f, v0 = 0.0f;
            if (tc_data->element_type == T_BYTE) {
                int8_t* s = (int8_t*)array_data(tc_data);
                u0 = (float)s[0] * ts + tbx;
                v0 = (float)s[1] * ts + tby;
            } else if (tc_data->element_type == T_SHORT) {
                int16_t* s = (int16_t*)array_data(tc_data);
                u0 = (float)s[0] * ts + tbx;
                v0 = (float)s[1] * ts + tby;
            } else if (tc_data->element_type == T_FLOAT) {
                float* s = (float*)array_data(tc_data);
                u0 = s[0] * ts + tbx;
                v0 = s[1] * ts + tby;
            }
            (void)u0; (void)v0;
            /* The stored textureS/T arrays hold the (u, v) barycentric
             * weights per JSR-184 — getTextureS/T interpret them with the
             * mesh's texcoord data downstream; storing the weights. */
            JavaArray* ts_arr = (JavaArray*)m3g_get_ref_field(ri, "textureS");
            if (!ts_arr || ts_arr->element_type != T_FLOAT || ts_arr->length < 1) {
                ts_arr = jvm_new_array(jvm, T_FLOAT, 1, NULL);
                if (ts_arr) m3g_set_ref_field(ri, "textureS", (JavaObject*)ts_arr);
            }
            JavaArray* tt_arr = (JavaArray*)m3g_get_ref_field(ri, "textureT");
            if (!tt_arr || tt_arr->element_type != T_FLOAT || tt_arr->length < 1) {
                tt_arr = jvm_new_array(jvm, T_FLOAT, 1, NULL);
                if (tt_arr) m3g_set_ref_field(ri, "textureT", (JavaObject*)tt_arr);
            }
            if (ts_arr && ts_arr->element_type == T_FLOAT && ts_arr->length >= 1) {
                ((jfloat*)array_data(ts_arr))[0] = best_u;
            }
            if (tt_arr && tt_arr->element_type == T_FLOAT && tt_arr->length >= 1) {
                ((jfloat*)array_data(tt_arr))[0] = best_v;
            }
        }
    }
    /* v34.50: JSR-184 pick() returns boolean — hit iff a node was found.
     * (Was NATIVE_RETURN_VOID; every spec-signature registration on
     * Group/World/Node needs the Z return — Quake's bullet loop drives
     * enemy damage/decals off it.) */
    return NATIVE_RETURN_INT(best_node ? 1 : 0);
}

/* ---- SkinnedMesh Java API over the v22 binding storage ---- */
static JavaValue native_skinnedmesh_init(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)thread; (void)arg_count;
    /* v30: the JSR-184 SPEC constructors are
     *   SkinnedMesh(VB, IB, App, Group skeleton) and
     *   SkinnedMesh(VB, IB[], App[], Group skeleton).
     * The descriptor-dispatched wrappers below know the form statically;
     * this entry keeps supporting the legacy (VB, IB, App, VB, IB) form. */
    JavaObject* sm = (JavaObject*)args[0].ref;
    JavaObject* vb = (JavaObject*)args[1].ref;
    JavaObject* ib = (JavaObject*)args[2].ref;
    JavaObject* app = (JavaObject*)args[3].ref;
    JavaObject* bones_vb = (JavaObject*)args[4].ref;
    JavaObject* bones_ib = (JavaObject*)args[5].ref;
    if (!sm) return NATIVE_RETURN_VOID();

    m3g_registry_register(sm, 0);
    m3g_set_ref_field(sm, "vertexBuffer", vb);
    m3g_set_ref_field(sm, "indexBuffer", ib);
    m3g_set_ref_field(sm, "appearance", app);
    m3g_set_ref_field(sm, "bones", bones_vb);
    m3g_set_ref_field(sm, "boneIndices", bones_ib);
    m3g_set_int_field(sm, "renderingEnable", 1);

    JavaObject* arg4 = (JavaObject*)args[4].ref;
    const char* arg4_class = (arg4 && arg4->header.clazz && arg4->header.clazz->class_name)
                             ? arg4->header.clazz->class_name : "";
    /* If the game (or the stub generator) passed a SKELETON GROUP in arg4
     * for the legacy descriptor, still record it as the skeleton. */
    if (strstr(arg4_class, "Group") != NULL || strstr(arg4_class, "World") != NULL) {
        m3g_set_ref_field(sm, "skeleton", arg4);
        return NATIVE_RETURN_VOID();
    }
    /* Derive bindings from the skeleton: each bone position is a 4-tuple
     * (boneNodeIndex placeholder, firstVertex, vertexCount, weight) and
     * boneIndices groups them in triples — mirrored from the M3G file
     * layout the v22 parser fills. Node references are linked lazily via
     * addTransform. */
    JavaArray* bone_ib = bones_ib ? (JavaArray*)m3g_get_ref_field(bones_ib, "data") : NULL;
    JavaObject* bones_va = bones_vb ? m3g_get_ref_field(bones_vb, "positions") : NULL;
    JavaArray* bone_pos = bones_va ? (JavaArray*)m3g_get_ref_field(bones_va, "data") : NULL;
    if (!bone_ib || !bone_pos) return NATIVE_RETURN_VOID();

    int nbones = (int)bone_ib->length / 3;
    if (nbones <= 0) return NATIVE_RETURN_VOID();
    int comps = m3g_get_int_field(bones_va, "componentCount", 4);
    jint* idx = (jint*)array_data(bone_ib);

    JavaArray* refs = jvm_new_array(jvm, DESC_OBJECT, nbones, NULL);
    JavaArray* first = jvm_new_array(jvm, T_INT, nbones, NULL);
    JavaArray* cnt = jvm_new_array(jvm, T_INT, nbones, NULL);
    JavaArray* wgt = jvm_new_array(jvm, T_INT, nbones, NULL);
    if (refs) m3g_set_ref_field(sm, "boneNodeRefs", (JavaObject*)refs);
    if (first) m3g_set_ref_field(sm, "boneFirstVertex", (JavaObject*)first);
    if (cnt) m3g_set_ref_field(sm, "boneVertexCount", (JavaObject*)cnt);
    if (wgt) m3g_set_ref_field(sm, "boneWeights", (JavaObject*)wgt);

    jint* fv = first ? (jint*)array_data(first) : NULL;
    jint* vc = cnt ? (jint*)array_data(cnt) : NULL;
    jint* wt = wgt ? (jint*)array_data(wgt) : NULL;

    for (int b = 0; b < nbones; b++) {
        int vi = idx[b*3];  /* first vertex of the triple */
        if (fv) fv[b] = (comps >= 2 && bone_pos->element_type == T_FLOAT)
            ? (jint)((float*)array_data(bone_pos))[vi*comps+1] : 0;
        if (vc) vc[b] = (comps >= 3 && bone_pos->element_type == T_FLOAT)
            ? (jint)((float*)array_data(bone_pos))[vi*comps+2] : 0;
        if (wt) wt[b] = (comps >= 4 && bone_pos->element_type == T_FLOAT)
            ? (jint)((float*)array_data(bone_pos))[vi*comps+3] : 255;
    }
    return NATIVE_RETURN_VOID();
}

/* v30: JSR-184 SkinnedMesh(VB, IB, App, Group skeleton). */
static JavaValue native_skinnedmesh_init_spec_single(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    if (!sm) return NATIVE_RETURN_VOID();
    m3g_registry_register(sm, 0);
    m3g_set_ref_field(sm, "vertexBuffer", (JavaObject*)args[1].ref);
    m3g_set_ref_field(sm, "indexBuffer", (JavaObject*)args[2].ref);
    m3g_set_ref_field(sm, "appearance", (JavaObject*)args[3].ref);
    m3g_set_ref_field(sm, "skeleton", (JavaObject*)args[4].ref);
    m3g_set_int_field(sm, "renderingEnable", 1);
    m3g_set_int_field(sm, "submeshCount", 1);
    /* Bone bindings arrive via SkinnedMesh.addTransform(). */
    return NATIVE_RETURN_VOID();
}

/* v30: JSR-184 SkinnedMesh(VB, IB[], App[], Group skeleton). */
static JavaValue native_skinnedmesh_init_spec_arrays(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    if (!sm) return NATIVE_RETURN_VOID();
    JavaArray* ibs = (JavaArray*)args[2].ref;
    JavaArray* apps = (JavaArray*)args[3].ref;
    m3g_registry_register(sm, 0);
    m3g_set_ref_field(sm, "vertexBuffer", (JavaObject*)args[1].ref);
    m3g_set_ref_field(sm, "skeleton", (JavaObject*)args[4].ref);
    if (ibs && ibs->element_type == DESC_OBJECT) {
        m3g_set_ref_field(sm, "indexBuffers", (JavaObject*)ibs);
        JavaObject** ib_arr = (JavaObject**)array_data(ibs);
        if (ibs->length > 0) m3g_set_ref_field(sm, "indexBuffer", ib_arr[0]);
        m3g_set_int_field(sm, "submeshCount", (int)ibs->length);
    }
    if (apps && apps->element_type == DESC_OBJECT) {
        m3g_set_ref_field(sm, "appearances", (JavaObject*)apps);
        JavaObject** app_arr = (JavaObject**)array_data(apps);
        if (apps->length > 0) m3g_set_ref_field(sm, "appearance", app_arr[0]);
    }
    m3g_set_int_field(sm, "renderingEnable", 1);
    return NATIVE_RETURN_VOID();
}

static JavaValue native_skinnedmesh_addTransform(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)thread; (void)arg_count;
    /* addTransform(Node bone, int firstVertex, int numVertices, int weight) */
    JavaObject* sm = (JavaObject*)args[0].ref;
    JavaObject* bone = (JavaObject*)args[1].ref;
    jint first = args[2].i, count = args[3].i, weight = args[4].i;
    if (!sm || !bone) return NATIVE_RETURN_VOID();

    JavaArray* refs = (JavaArray*)m3g_get_ref_field(sm, "boneNodeRefs");
    JavaArray* firsta = (JavaArray*)m3g_get_ref_field(sm, "boneFirstVertex");
    JavaArray* cnta = (JavaArray*)m3g_get_ref_field(sm, "boneVertexCount");
    JavaArray* wgta = (JavaArray*)m3g_get_ref_field(sm, "boneWeights");
    if (!refs || !firsta || !cnta || !wgta) return NATIVE_RETURN_VOID();

    int old = refs->length;
    JavaArray* nrefs = jvm_new_array(jvm, DESC_OBJECT, old + 1, NULL);
    JavaArray* nfirst = jvm_new_array(jvm, T_INT, old + 1, NULL);
    JavaArray* ncnt = jvm_new_array(jvm, T_INT, old + 1, NULL);
    JavaArray* nwgt = jvm_new_array(jvm, T_INT, old + 1, NULL);
    if (!nrefs || !nfirst || !ncnt || !nwgt) return NATIVE_RETURN_VOID();
    if (old) {
        memcpy(array_data(nrefs), array_data(refs), (size_t)old * sizeof(void*));
        memcpy(array_data(nfirst), array_data(firsta), (size_t)old * sizeof(jint));
        memcpy(array_data(ncnt), array_data(cnta), (size_t)old * sizeof(jint));
        memcpy(array_data(nwgt), array_data(wgta), (size_t)old * sizeof(jint));
    }
    ((JavaObject**)array_data(nrefs))[old] = bone;
    ((jint*)array_data(nfirst))[old] = first;
    ((jint*)array_data(ncnt))[old] = count;
    ((jint*)array_data(nwgt))[old] = weight;
    m3g_set_ref_field(sm, "boneNodeRefs", (JavaObject*)nrefs);
    m3g_set_ref_field(sm, "boneFirstVertex", (JavaObject*)nfirst);
    m3g_set_ref_field(sm, "boneVertexCount", (JavaObject*)ncnt);
    m3g_set_ref_field(sm, "boneWeights", (JavaObject*)nwgt);
    return NATIVE_RETURN_VOID();
}

static JavaValue native_skinnedmesh_getBoneTransform(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    JavaObject* bone = (JavaObject*)args[1].ref;
    JavaObject* transform = (JavaObject*)args[2].ref;
    if (bone && transform) {
        M3GTransform t;
        m3g_build_node_transform(bone, &t);
        set_native_transform(transform, &t);
    }
    (void)sm;
    return NATIVE_RETURN_VOID();
}

static JavaValue native_skinnedmesh_getSkeleton(JVM* jvm, JavaThread* thread, JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* sm = (JavaObject*)args[0].ref;
    JavaArray* refs = sm ? (JavaArray*)m3g_get_ref_field(sm, "boneNodeRefs") : NULL;
    if (refs && refs->length > 0)
        return NATIVE_RETURN_OBJECT(((JavaObject**)array_data(refs))[0]);
    JavaObject* bones_vb = sm ? m3g_get_ref_field(sm, "bones") : NULL;
    return NATIVE_RETURN_OBJECT(bones_vb);
}

