/* Transformable.getCompositeTransform(Transform) — JSR-184 §Transformable.
 * Writes the node's composed T * R * S matrix into the Transform. Registered
 * on Node (the stub hierarchy folds Transformable's fields into Node, so the
 * native_find superclass walk from Mesh/Camera/Light/Sprite3D/Group/World
 * resolves it) and on Transformable itself. */
static JavaValue native_transformable_getCompositeTransform(JVM* jvm, JavaThread* thread,
                                                             JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    JavaObject* transform = (JavaObject*)args[1].ref;
    if (!obj || !transform) return NATIVE_RETURN_VOID();

    M3GTransform t;
    m3g_build_node_transform(obj, &t);
    set_native_transform(transform, &t);
    return NATIVE_RETURN_VOID();
}

