/* Image2D.setImage(javax.microedition.lcdui.Image) — M3G 1.1. Copies the
 * pixels from a mutable LCDUI Image into this (mutable) Image2D. */
static JavaValue native_image2d_setImage(JVM* jvm, JavaThread* thread,
                                         JavaValue* args, int arg_count) {
    (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    JavaObject* image = (JavaObject*)args[1].ref;
    if (!obj || !image) return NATIVE_RETURN_VOID();

    int w = m3g_get_int_field(image, "width", 0);
    int h = m3g_get_int_field(image, "height", 0);
    JavaArray* src_px = (JavaArray*)m3g_get_ref_field(image, "pixels");
    if (w <= 0 || h <= 0 || !src_px || src_px->element_type != T_INT) {
        /* fall back to the Image's native graphics buffer if present */
        return NATIVE_RETURN_VOID();
    }
    int n = w * h;
    if ((int)src_px->length < n) n = (int)src_px->length;
    JavaArray* dst_px = (JavaArray*)m3g_get_ref_field(obj, "pixels");
    if (!dst_px || dst_px->element_type != T_INT || (int)dst_px->length < w * h) {
        dst_px = jvm_new_array(jvm, T_INT, w * h, NULL);
        if (!dst_px) return NATIVE_RETURN_VOID();
        m3g_set_ref_field(obj, "pixels", (JavaObject*)dst_px);
    }
    jint* dst = (jint*)array_data(dst_px);
    jint* src = (jint*)array_data(src_px);
    for (int i = 0; i < n; i++) dst[i] = src[i];
    m3g_set_int_field(obj, "width", w);
    m3g_set_int_field(obj, "height", h);
    m3g_mark_image2d_updated(obj);
    return NATIVE_RETURN_VOID();
}

/* VertexArray.get(int firstVertex, int numVertices, short[] dst) — spec form
 * (the byte[] form existed; the int[] form was non-spec). */
static JavaValue native_vertexarray_get_short(JVM* jvm, JavaThread* thread,
                                              JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    jint first = args[1].i;
    jint count = args[2].i;
    JavaArray* dst = (JavaArray*)args[3].ref;
    if (!obj || !dst || dst->element_type != T_SHORT) return NATIVE_RETURN_VOID();

    JavaArray* data = (JavaArray*)m3g_get_ref_field(obj, "data");
    if (!data) return NATIVE_RETURN_VOID();
    int comp = m3g_get_int_field(obj, "componentCount", 3);
    int vcount = m3g_get_int_field(obj, "vertexCount", 0);
    if (first < 0 || count < 0 || first + count > vcount) return NATIVE_RETURN_VOID();
    int need = count * comp;
    if ((int)dst->length < need || (int)data->length < (first + count) * comp) {
        return NATIVE_RETURN_VOID();
    }
    jshort* d = (jshort*)array_data(dst);
    if (data->element_type == T_SHORT) {
        jshort* s = (jshort*)array_data(data);
        for (int i = 0; i < need; i++) d[i] = s[first * comp + i];
    } else if (data->element_type == T_BYTE) {
        int8_t* s = (int8_t*)array_data(data);
        for (int i = 0; i < need; i++) d[i] = (jshort)s[first * comp + i];
    }
    return NATIVE_RETURN_VOID();
}

