/* v30: JSR-184 constructor defaults for the scene-graph classes. The stub
 * fields zero-initialize, which silently DISABLED rendering/lighting for
 * every API-created object: a `new Light()` had renderingEnable=0 (the scene
 * light collector skips disabled nodes -> the light never lit anything),
 * and `new Camera()` had no identity GENERIC projection (spec default). */
static JavaValue native_light_init(JVM* jvm, JavaThread* thread,
                                   JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    if (!obj) return NATIVE_RETURN_VOID();
    /* JSR-184 §Light defaults: DIRECTIONAL, white, intensity 1,
     * attenuation (1,0,0), spot cone 45 deg, exponent 0. */
    m3g_set_int_field(obj, "mode", 129);
    m3g_set_int_field(obj, "lightType", 129);
    m3g_set_int_field(obj, "color", 0x00FFFFFF);
    m3g_set_float_field(obj, "intensity", 1.0f);
    m3g_set_float_field(obj, "constantAttenuation", 1.0f);
    m3g_set_float_field(obj, "linearAttenuation", 0.0f);
    m3g_set_float_field(obj, "quadraticAttenuation", 0.0f);
    m3g_set_float_field(obj, "spotAngle", 45.0f);
    m3g_set_float_field(obj, "spotExponent", 0.0f);
    m3g_set_int_field(obj, "renderingEnable", 1);   /* v30: zero-init guard */
    m3g_set_int_field(obj, "pickingEnable", 1);
    return NATIVE_RETURN_VOID();
}

static JavaValue native_camera_init(JVM* jvm, JavaThread* thread,
                                    JavaValue* args, int arg_count) {
    (void)jvm; (void)thread; (void)arg_count;
    JavaObject* obj = (JavaObject*)args[0].ref;
    if (!obj) return NATIVE_RETURN_VOID();
    /* JSR-184 §Camera: "a camera with a GENERIC identity projection". */
    m3g_set_int_field(obj, "projectionType", 0);  /* GENERIC */
    {
        JavaArray* arr = jvm_new_array(jvm, T_FLOAT, 16, NULL);
        if (arr) {
            float* m = (float*)array_data(arr);
            memset(m, 0, 16 * sizeof(float));
            m[0] = m[5] = m[10] = m[15] = 1.0f;
            m3g_set_ref_field(obj, "genericMatrix", (JavaObject*)arr);
        }
    }
    m3g_set_int_field(obj, "renderingEnable", 1);   /* v30: zero-init guard */
    m3g_set_int_field(obj, "pickingEnable", 1);
    return NATIVE_RETURN_VOID();
}

/* v34.74 (A-9, JSR-184 Node defaults): plain Node had NO <init> native —
 * jvm_new_object zero-fills every stub field, so a fresh Node reported
 * isRenderingEnable()=false, getScale()=(0,0,0) and getAlphaFactor()=0.
 * The renderer's degenerate-guards (scale 0→1, alpha 0→1) hid most of it
 * at render time, but the API answers and VISIBILITY/PICKABILITY defaults
 * were wrong for every API-created plain Node. */
